"""Authored beginner curricula; rerun to regenerate the data module."""
import json
from pathlib import Path
lessons=[]
def add(lang,slug,title,concept,why,example,walk,task,solution,output,quiz,options,answer,explanation,pitfall,challenge,**extra):
 n=sum(l['language']==lang for l in lessons)
 lessons.append(dict(id=f'{lang}-{slug}',language=lang,title=title,module=['First steps','Build your toolkit','Put it together'][min(n//4,2)],level='Beginner' if n<8 else 'Next steps',minutes=8 if n<4 else 12,concept=concept,why=why,example=example,walk=walk,task=task,solution=solution,output=output,quiz=dict(q=quiz,options=options,answer=answer,explanation=explanation),pitfall=pitfall,challenge=challenge,hints=[walk[0],walk[-1]],starter=extra.pop('starter',{'python':'# Write your program below\n','javascript':'// Write your program below\n','java':'public class Main {\n    public static void main(String[] args) {\n        // Write your code here\n    }\n}\n','html':'<!-- Write your HTML here -->\n','css':'/* Write your CSS here */\n'}[lang]),**extra))
def java(body):return 'public class Main {\n    public static void main(String[] args) {\n'+ '\n'.join('        '+line for line in body.splitlines())+'\n    }\n}'
for lang in ['python','javascript','java']:
 py=lang=='python';js=lang=='javascript'
 def p(value):return f'print({value})' if py else f'console.log({value});' if js else f'System.out.println({value});'
 def wrap(code):return java(code) if lang=='java' else code
 def declaration(name,value,kind='int'):return f'{name} = {value}' if py else f'let {name} = {value};' if js else f'{kind} {name} = {value};'
 intro=('Python runs statements from top to bottom. print(...) sends a value to the output area. Text inside matching quotes is called a string.' if py else 'JavaScript runs statements from top to bottom. console.log(...) sends a value to the console. Text inside matching quotes is called a string.' if js else 'Java starts this program in main. The class Main holds the program; main is its entry point. System.out.println(...) writes one line to the console. Text inside double quotes is a String.')
 add(lang,'hello','Hello, world! — your first program',intro+' A program is simply a set of instructions that the computer follows exactly. You do not need variables or functions of your own yet.','Output lets you see what your program did. This is the first tool you will use when learning or finding a mistake.',wrap(p('"Hello, learner!"')),['Find the output instruction in the example. The parentheses hold the value to display.','The quotes mark text; they are not printed. Capital letters, spaces and punctuation inside the quotes are printed.','Change only the message to "Hello, world!". Keep the closing quote and parenthesis.' ],'Display exactly Hello, world! on one line.',wrap(p('"Hello, world!"')),'Hello, world!','What appears in the output when you print "Hi"?',['Hi','"Hi"','Nothing'],0,'Quotes describe a string in the source code. The displayed string does not include those surrounding quotes.','A missing closing quote is a syntax error. Read the error and check the matching pairs before changing everything.','Change the greeting to your name, then add a second output line. Predict both lines before checking.',terms=[['Program','Instructions that a computer follows.'],['String','A sequence of characters, such as a message.'],['Output','Information a program displays.']])
 add(lang,'addition','Add two numbers','Numbers without quotes are numeric values. The + operator adds them. An expression such as 2 + 3 is evaluated first, and the output instruction then displays its result.','This tiny calculation is the foundation of bills, counters and scores.',wrap(p('2 + 3')),['Start with two numeric values, 2 and 3, without quotes.','The computer evaluates the expression 2 + 3 to get 5.','For your task, replace those values with 7 and 5. Print the expression, not a quoted message.'],'Display the result of adding 7 and 5. Write an addition expression so you practise the operator.',wrap(p('7 + 5')),'12','What does 7 + 5 evaluate to?',['75','12','7 + 5'],1,'With two numbers, + means addition. The expression is evaluated before the result is displayed.','"7 + 5" is text, so printing it displays the expression rather than calculating it.','Add three numbers. Then try subtraction and explain why the result changes.',terms=[['Expression','Code that produces a value.'],['Operator','A symbol that performs an operation, such as +.']])
 ex=declaration('apples','3')+'\n'+p('apples');sol=declaration('first','7')+'\n'+declaration('second','5')+'\n'+p('first + second')
 add(lang,'variables','Give values a name','A variable is a name associated with a value. Think of a labeled box: the name helps you find and reuse the value. Assignment stores the value on the right under the name on the left. '+('Python assigns with = and does not require a type declaration.' if py else 'JavaScript uses let for a binding you may reassign. const is for a binding you will not reassign.' if js else 'Java declares the type before the name. int stores whole numbers; String stores text.'),'Names explain what numbers mean, so changing a price or quantity does not mean rewriting every calculation.',wrap(ex),['Read the assignment as "store 3 using the name apples", not as a maths equality test.','Use the name without quotes when you want its value.','Create first and second with values 7 and 5, then add those two names.'],'Store 7 in first and 5 in second. Display their sum using the variables.',wrap(sol),'12','What does printing apples display after apples is assigned 3?',['apples','3','An empty box'],1,'An unquoted variable name refers to its stored value. A quoted name would be literal text.','Using a variable before assigning it causes an error. Spelling and capitalization must match.','Change second to 8. Predict the new result without changing the output expression.',terms=[['Variable','A name for a value.'],['Assignment','Giving a variable its value using =.']])
 add(lang,'arithmetic','Build a small calculation','Arithmetic operators include +, -, * and /. Multiplication and division happen before addition and subtraction. Parentheses let you choose what happens first. '+('In Python / returns a floating-point result; // performs floor division.' if py else 'JavaScript / can produce a fraction.' if js else 'Dividing two int values in Java discards the fractional part. Use a double operand when you need a fraction.'),'A shopping subtotal is price multiplied by quantity; a discount can then be subtracted.',wrap(p('(4 + 2) * 3')),['Calculate the parentheses first: 4 + 2 becomes 6.','Multiply 6 by 3 to get 18. Without parentheses, 4 + 2 * 3 would be 10.','For the task, multiply price 20 by quantity 3, then subtract the discount 5.'],'Display the total for 3 items costing 20 each, after subtracting a discount of 5.',wrap(p('20 * 3 - 5')),'55','What is (4 + 2) * 3?',['10','18','24'],1,'Parentheses group 4 + 2. That gives 6; then 6 times 3 gives 18.','Do not use x for multiplication. Programming languages use *.','Use variables named price, quantity and discount. Try zero quantity and think about whether a discount should still apply.',terms=[['Precedence','The order in which operators are evaluated.']])
 add(lang,'strings','Join text into a greeting','Strings can contain spaces, punctuation and digits. Joining strings is called concatenation. A number and its text representation are different values. '+('Use str(...) to convert a number when concatenating with text.' if py else 'JavaScript and Java can join a string and a number using +, but explicit choices keep your intent clear.'),'Greetings, labels and status messages combine fixed words with changing information.',wrap(declaration('name','"Mira"','String')+'\n'+p('"Hi, " + name')),['The first string includes a comma and a space. Those characters matter.','The + operator joins the two strings in order.','For the task, store "Sam" as name and join "Hello, " with name and "!".'],'Use a name variable holding Sam. Display Hello, Sam!',wrap(declaration('name','"Sam"','String')+'\n'+p('"Hello, " + name + "!"')),'Hello, Sam!','Why is the space included inside "Hi, "?',['It separates words in the output','It declares a variable','It starts a comment'],0,'The program displays the exact characters in each string. It will not add a missing space automatically.','Text + text joins strings. Do not expect "7" + "5" to calculate 12.','Create a sentence containing your name and a hobby.',terms=[['Concatenation','Joining strings end to end.']])
 cmp='True' if py else 'true'
 op='==' if py or lang=='java' else '==='
 add(lang,'comparisons','Ask a yes-or-no question','A comparison produces a Boolean: true or false. Use >, <, >= and <= to compare numbers. '+f'Use {op} for equality here; = assigns a value. '+('Python spells its Boolean values True and False.' if py else 'JavaScript and Java spell Boolean values true and false.'),'Comparisons let a program decide whether a score passes or stock is available.',wrap(p('8 >= 5')),['Compare 8 with 5. Eight is greater, so the condition is true.','The equals part of >= also allows the boundary value itself.','Compare 10 >= 10 in your program.'],'Display the result of checking whether 10 is greater than or equal to 10.',wrap(p('10 >= 10')),cmp,'Does >= include equality?',['Yes','No','Only for strings'],0,'The condition accepts values greater than the boundary and values equal to it.','Confusing > with >= changes what happens exactly at the boundary. Always check that case.','Compare 9, 10 and 11 against the same boundary and predict each result.',terms=[['Boolean','One of two logical values: true or false.'],['Boundary','The value where a condition changes behavior.']])
 branch=('score = 8\nif score >= 5:\n    print("Pass")\nelse:\n    print("Try again")' if py else declaration('score','8')+'\nif (score >= 5) {\n    '+p('"Pass"')+'\n} else {\n    '+p('"Try again"')+'\n}')
 add(lang,'branches','Choose a path with if / else','An if statement runs a block only when its condition is true. The else block runs when that condition is false. Only one of these two branches runs. '+('Python uses a colon and indentation to mark each block.' if py else 'Braces group the statements belonging to each block.'),'A result message should depend on a score instead of always saying the same thing.',wrap(branch),['Assign the score before testing it.','Check score >= 5. The example runs the Pass branch because 8 is at least 5.','Set score to 3 for the task. Preserve both branches so you can later test other scores.'],'Create score = 3. If score is at least 5, print Pass; otherwise print Try again.',wrap(branch.replace('score = 8','score = 3')),'Try again','Which branch runs when score is 3 and the condition is score >= 5?',['if','else','Both'],1,'The condition is false for 3. The else branch therefore runs.','An output statement outside the branch runs regardless of the condition. Check your indentation or braces.','Change score to 5, then 4. Confirm both sides of the boundary.',terms=[['Condition','An expression interpreted as true or false.'],['Block','Statements grouped to run together.']])
 loop=('for number in range(1, 4):\n    print(number)' if py else 'for ('+('let' if js else 'int')+' number = 1; number <= 3; number++) {\n    '+p('number')+'\n}')
 add(lang,'loops','Repeat with a loop','A loop repeats instructions. A counter can tell you which repetition you are on. '+('range(1, 4) produces 1, 2 and 3: the stop value is excluded.' if py else 'A for loop initializes a counter, checks a condition, runs its body, and updates the counter before checking again.'),'Loops replace repeated lines of code and work even when the amount of data grows.',wrap(loop),['Start the counter at 1.','Print the current number during each repetition.','Stop after 3. Python excludes the range stop value 4; JavaScript and Java use <= 3 here.'],'Display 1, 2 and 3 on separate lines using a loop.',wrap(loop),'1\n2\n3','How many lines does this loop print?',['2','3','4'],1,'It visits the values 1, 2 and 3 exactly once each.','A wrong stopping condition may skip the last value or repeat forever. Work out the first and last iterations on paper.','Print 1 through 5. Then print only 2, 4 and 6.',terms=[['Iteration','One execution of the loop body.'],['Counter','A value that tracks the loop position.']])
 collection=('scores = [4, 7, 9]\nprint(scores[0])' if py else 'let scores = [4, 7, 9];\nconsole.log(scores[0]);' if js else 'int[] scores = {4, 7, 9};\nSystem.out.println(scores[0]);')
 add(lang,'collections','Keep related values together','A '+('list' if py else 'array')+' holds several values in order. Indexing selects a single value by position. In all three languages here, the first position is index 0, the second is 1, and the third is 2.','A collection can hold test scores or item prices without inventing a separate variable for each item.',wrap(collection),['Create the collection containing 4, 7 and 9 in that order.','scores[0] selects 4. The brackets after the name are an index lookup.','For the task, select index 1, which contains 7.'],'Store 4, 7 and 9 in scores. Display the second value using an index.',wrap(collection.replace('scores[0]','scores[1]')),'7','Which index selects the first value?',['0','1','-2'],0,'These languages use zero-based indexing, so index 0 is the first position.','The third value is at index 2. Index 3 is beyond a three-item collection.','Change the second score and print it again. Explain the difference between the index and the value.',terms=[['Index','A position used to access a collection value.']])
 fn=('def add(a, b):\n    return a + b\n\nprint(add(2, 3))' if py else 'function add(a, b) {\n    return a + b;\n}\nconsole.log(add(2, 3));' if js else 'public class Main {\n    static int add(int a, int b) {\n        return a + b;\n    }\n    public static void main(String[] args) {\n        System.out.println(add(2, 3));\n    }\n}')
 add(lang,'functions','Reuse an idea with a function','A function groups instructions under a name. Parameters are names for incoming values. Calling the function supplies arguments. return sends a result back to the caller; it does not automatically display it. '+('In Java, a function defined in a class is called a method. static lets main call this method without creating an object.' if lang=='java' else ''),'You can write a calculation once and call it with different values instead of copying the code.',fn,['Define add with two parameters, a and b.','Return their sum from the function.','Call add(7, 5) and display the returned result for your task.'],'Define add(a, b), returning their sum. Call it with 7 and 5 and display the result.',fn.replace('add(2, 3)','add(7, 5)'),'12','Does return automatically print a value?',['Yes','No','Only for addition'],1,'return gives a value back to the caller. A separate output instruction displays it.','Printing inside a function is not the same as returning a value. Follow the requested function contract.','Call your function with 0 and 5, then with -2 and 2.',terms=[['Parameter','A named input in a function definition.'],['Argument','An actual value supplied in a call.'],['Return','Send a result back to the caller.']])
 bug=declaration('width','4')+'\n'+declaration('height','3')+'\n'+p('width + height')
 add(lang,'debug','Find and fix a logic mistake','A program can run without errors and still give the wrong answer. That is a logic bug. Debugging means comparing what you expected with what happened, then checking the smallest part that explains the difference.','You will spend time reading and correcting code as well as writing it. A small predictable input is a powerful tool.',wrap(bug),['For a rectangle 4 units wide and 3 units high, calculate the area on paper: 12 square units.','The example adds width and height, producing 7. Both variables are fine; the operator is wrong.','Replace + with * to compute width times height.'],'Fix the example so it calculates the area of the 4-by-3 rectangle. Display 12.',wrap(bug.replace('width + height','width * height')),'12','The program runs but computes the wrong formula. What kind of mistake is this?',['Logic bug','Missing quote','Network error'],0,'The syntax is valid; the instructions describe the wrong calculation.','Do not change the expected answer to match incorrect code. Check the real-world rule first.','Try width 0 and height 5. Is the output consistent with an area of zero?',starter=wrap(bug),terms=[['Logic bug','Valid code that performs the wrong operation.'],['Test case','An input and the result you expect for it.']])
 total=('prices = [10, 20, 5]\ntotal = 0\nfor price in prices:\n    total = total + price\nprint(total)' if py else 'let prices = [10, 20, 5];\nlet total = 0;\nfor (let price of prices) {\n    total = total + price;\n}\nconsole.log(total);' if js else 'int[] prices = {10, 20, 5};\nint total = 0;\nfor (int price : prices) {\n    total = total + price;\n}\nSystem.out.println(total);')
 add(lang,'project','Mini project: a shopping total','An accumulator starts with an initial value and is updated as you visit a collection. For a sum, start at zero and add each item once. This combines variables, collections and loops into one useful program.','The same pattern totals marks, expenses and stock counts.',wrap(total),['Create prices containing 10, 20 and 5, and initialize total to 0 before the loop.','Trace each update: 0 + 10 = 10, then 10 + 20 = 30, then 30 + 5 = 35.','For the task, use prices 12, 8 and 5. Print total only after the loop ends.'],'Build a shopping-total program for prices 12, 8 and 5. Use a collection and a loop; display one final total of 25.',wrap(total.replace('10, 20, 5','12, 8, 5')),'25','Where should total = 0 go?',['Before the loop','Inside every repetition','After printing'],0,'Initialize once before the loop so each addition builds on the previous total.','Resetting total to zero inside the loop loses the running sum. Printing inside the loop shows partial totals.','Add a fourth item. Then use an empty collection and explain why starting at zero gives a sensible result.',terms=[['Accumulator','A variable that builds a result step by step.']])
Path('src/data/foundations.json').write_text(json.dumps(lessons,indent=2)+'\n')
# HTML checks describe DOM structure, not a string match against the reference.
html_rows=[
('hello','Hello, web! — your first page','HTML describes the meaning and structure of a page. A tag such as <h1> starts an element; </h1> closes it. The text between them is its content. HTML is markup, not a language for calculations.','Browsers use this structure to display content and expose it to assistive technology.','<h1>Hello, web!</h1>',['The h1 element identifies the main heading.','The slash in </h1> closes the element. Keep opening and closing tags around the content.','Write your own heading using the exact words Hello, world! for this exercise.'],'Create one h1 containing Hello, world!','<h1>Hello, world!</h1>','What is h1 used for?',['A main heading','Adding numbers','Choosing a text color'],0,'h1 identifies the main heading; styling can later change its appearance.','Do not type the closing tag as <h1/>. Normal HTML heading elements need an explicit closing tag.','Add a paragraph introducing yourself.',[dict(selector='h1',text='Hello, world!',label='Main heading says Hello, world!')]),
('paragraphs','Headings and readable paragraphs','Headings organize ideas; paragraphs group normal text. h1 through h6 describe heading levels, not merely sizes. Use a clear hierarchy so a reader can scan the page.','Good structure helps both sighted readers and screen-reader users navigate.','<h1>My notebook</h1>\n<h2>Today</h2>\n<p>I wrote my first page.</p>',['h1 names the whole page.','h2 introduces a section inside that page.','p contains a paragraph of ordinary text.'],'Create an h1 called My learning journal, an h2 called Day one, and a nonempty paragraph describing what you learned.','<h1>My learning journal</h1>\n<h2>Day one</h2>\n<p>I learned how tags organize a page.</p>','Should you choose h3 just because you want smaller text?',['Yes','No'],1,'Choose heading levels for structure. CSS controls their visual size.','Do not put a heading inside a paragraph. These are separate blocks of content.','Add a Day two section at the same heading level.',[dict(selector='h1',text='My learning journal',label='Page heading'),dict(selector='h2',text='Day one',label='Section heading'),dict(selector='p',nonempty=True,label='A paragraph of your own')]),
('links','Make a useful link','An anchor element, a, creates a link when it has an href attribute. Attributes provide extra information in the opening tag. Link text should tell a reader where the link goes.','Links connect pages and resources. Descriptive text makes them easier to understand.','<a href="https://example.com">Visit Example</a>',['a is the element name.','href holds the destination URL; quote its value.','The text inside the element is the clickable label.'],'Add a link with href https://example.com and the visible text Explore Example.','<a href="https://example.com">Explore Example</a>','Which attribute holds the destination?',['href','color','src'],0,'href tells the browser where the anchor points.','A link labeled Click here loses meaning when read without nearby context. Name its destination.','Add a paragraph explaining why someone might visit the link.',[dict(selector='a',text='Explore Example',attribute='href',value='https://example.com',label='A descriptive link with the requested destination')]),
('lists','Group items in a list','ul creates an unordered list, while ol creates an ordered list. Each item is an li element inside the list. Use an ordered list when sequence matters.','Lists express relationships that separate paragraphs cannot communicate as clearly.','<ul>\n  <li>Read</li>\n  <li>Practise</li>\n</ul>',['The outer ul groups the items.','Each li contains one item.','Use ol for the task because the learning steps have an order.'],'Create an ordered list with three items: Read, Practise, Review.','<ol>\n  <li>Read</li>\n  <li>Practise</li>\n  <li>Review</li>\n</ol>','Which element is appropriate for numbered steps?',['ul','ol','p'],1,'ol communicates that the sequence is meaningful.','Do not place bare text directly inside a list instead of li elements.','Turn the list into an unordered list and explain what meaning changed.',[dict(selector='ol > li',count=3,label='Three ordered steps'),*[dict(selector=f'ol > li:nth-child({i+1})',text=t,label=f'Step {i+1}: {t}') for i,t in enumerate(['Read','Practise','Review'])]]),
('images','Images need a text alternative','img embeds an image using src. Its alt attribute describes the image when it carries information. Decorative images use alt="" so assistive technology can skip them. img is a void element: it does not have a closing tag.','An image may fail to load, or a reader may use a screen reader. Useful alt text preserves its meaning.','<img src="missing-photo.jpg" alt="A student reading at a desk">',['src identifies the resource. This example intentionally has no bundled photo, so its alternative may be visible.','alt communicates the image meaning rather than the filename.','Use the given filename and meaningful text for the task. External images are blocked in the lesson preview.'],'Add an img with src study.jpg and alt A notebook beside a laptop. The preview may show alt text instead of a picture.','<img src="study.jpg" alt="A notebook beside a laptop">','What should alt convey for an informative image?',['Its meaning','Only the file size','Nothing in every case'],0,'Describe the information that would otherwise be lost without the image.','An absent alt attribute is different from an intentionally empty alternative for a decorative image.','Describe an image of a chart: what important finding would the text need to communicate?',[dict(selector='img',attribute='src',value='study.jpg',label='Image source'),dict(selector='img',attribute='alt',value='A notebook beside a laptop',label='Meaningful alternative text')]),
('semantic','Give the page meaningful regions','Semantic elements describe purpose. header contains introductory material; nav contains navigation; main contains primary page content; footer contains concluding information. They are more informative than using div for everything.','Named regions help people and software understand a page without relying on its visual design.','<header><h1>My site</h1></header>\n<main><p>Welcome.</p></main>\n<footer><p>Made by me.</p></footer>',['The header introduces the page.','The main element holds the primary content, not repeated navigation.','Keep the footer outside main for this page-level structure.'],'Create a header with an h1, one main with a paragraph, and a footer with a paragraph. Use your own nonempty text.','<header><h1>My learning space</h1></header>\n<main><p>I am learning HTML.</p></main>\n<footer><p>Built with care.</p></footer>','Which element contains the primary page content?',['main','footer','nav'],0,'main identifies the content unique to the page.','Do not choose semantic elements solely because of default styling. Choose them for meaning.','Add nav inside the header with a descriptive link.',[dict(selector='header h1',nonempty=True,label='Heading inside header'),dict(selector='main',count=1,label='One main region'),dict(selector='main p',nonempty=True,label='Main paragraph'),dict(selector='footer p',nonempty=True,label='Footer paragraph')]),
('forms','Label an input clearly','Forms collect information. A label names an input; its for attribute matches the input id. type="email" enables email-oriented browser behavior. name identifies the field when form data is submitted.','Visible labels make forms usable even after placeholder text disappears.','<label for="name">Your name</label>\n<input id="name" name="name" type="text">',['The label text explains what to enter.','for="name" and id="name" connect the two elements.','For the exercise, connect the label to an email input and mark it required.'],'Create a label Email linked to an input with id email, name email, type email and required.','<label for="email">Email</label>\n<input id="email" name="email" type="email" required>','What links a label to an input?',['Matching for and id','Matching colors','The placeholder alone'],0,'The label for value matches the input id, creating a programmatic association.','A placeholder is a hint, not a substitute for a label. Browser validation also does not replace server validation.','Add a short instruction explaining why the email is requested.',[dict(selector='label[for="email"]',text='Email',label='Associated Email label'),dict(selector='input#email[name="email"][type="email"][required]',count=1,label='Required email field')]),
('buttons','Buttons perform actions','Use a button for an action and a link for navigation. Inside a form, type="submit" submits; type="button" avoids unintended submission. Native buttons provide keyboard interaction without rebuilding it yourself.','Correct elements make interactive interfaces easier to operate.','<button type="button">Show hint</button>',['The text gives the button an accessible name.','type="button" makes it an ordinary button.','The exercise builds a submit button inside a form. No backend is connected.'],'Create a form containing a button with type submit and the label Send message.','<form>\n  <button type="submit">Send message</button>\n</form>','What is the better element for a page action?',['button','A clickable paragraph'],0,'A native button includes expected keyboard behavior and semantics.','Do not assume a div becomes accessible just because it has a click handler.','Add a labeled message field above the button.',[dict(selector='form button[type="submit"]',text='Send message',label='Named submit button inside a form')]),
('tables','Describe tabular information','A table represents data organized in rows and columns. caption names it; tr is a row; th is a header cell; td is a data cell. scope helps describe whether a header applies to a row or a column.','Tables are useful for schedules or results, but should not be used to arrange an entire page layout.','<table>\n <caption>Scores</caption>\n <tr><th scope="col">Name</th><th scope="col">Score</th></tr>\n <tr><td>Mira</td><td>8</td></tr>\n</table>',['The caption identifies the table.','The first row uses header cells for Name and Score.','The data row contains the values under those headings.'],'Create a table captioned Scores with two column headers Name and Score, and a row containing Sam and 9.','<table>\n <caption>Scores</caption>\n <tr><th scope="col">Name</th><th scope="col">Score</th></tr>\n <tr><td>Sam</td><td>9</td></tr>\n</table>','Should a table be used just to position a sidebar?',['Yes','No'],1,'Use CSS for page layout. Tables communicate relationships in tabular data.','Bold text inside td is not a semantic header. Use th for header cells.','Add another data row, keeping the number and order of cells consistent.',[dict(selector='caption',text='Scores',label='Table caption'),dict(selector='th[scope="col"]',count=2,label='Two column headers'),dict(selector='th:nth-child(1)',text='Name',label='Name header'),dict(selector='th:nth-child(2)',text='Score',label='Score header'),dict(selector='td:nth-child(1)',text='Sam',label='Sam data cell'),dict(selector='td:nth-child(2)',text='9',label='Score data cell')]),
('project','Mini project: your learning page','Combine semantic regions, headings, paragraphs and a list into a small page. Plan the content first. Add styles only after the structure communicates the information clearly.','A complete page gives the separate elements a purpose and provides the foundation for the CSS course.','<main>\n <h1>My learning journey</h1>\n <p>One step at a time.</p>\n</main>',['Write the main heading and a short introduction.','Add a section with an h2 and a list of three goals.','Place a descriptive resource link in a footer outside main.'],'Build one main containing an h1, a paragraph and a section with an h2 and a three-item list. Add a footer with a link to https://example.com. Use your own text.','<main>\n <h1>My learning journey</h1>\n <p>I am building confidence with code.</p>\n <section>\n  <h2>My goals</h2>\n  <ul><li>Learn HTML</li><li>Style with CSS</li><li>Build a page</li></ul>\n </section>\n</main>\n<footer><a href="https://example.com">Explore a resource</a></footer>','What should you plan before choosing colors?',['The content and its structure','Only the shadow size'],0,'Meaningful content and structure provide the foundation for visual styling.','A visual preview cannot tell you everything about accessibility. Review headings, labels and link names as well.','Use this page as a starting point for your own portfolio introduction.',[dict(selector='main',count=1,label='One main'),dict(selector='main h1',nonempty=True,label='Main heading'),dict(selector='main p',nonempty=True,label='Introduction'),dict(selector='main section h2',nonempty=True,label='Section heading'),dict(selector='main section li',count=3,label='Three learning goals'),dict(selector='footer a[href="https://example.com"]',nonempty=True,label='Descriptive footer link')])]
for row in html_rows:
 slug,title,concept,why,example,walk,task,sol,q,opts,ans,exp,pit,challenge,checks=row
 add('html',slug,title,concept,why,example,walk,task,sol,'',q,opts,ans,exp,pit,challenge,checks=checks,terms=[['Element','An HTML building block, usually with an opening tag, content and closing tag.'],['Attribute','Extra information written in an opening tag.']])
fixture='<main><article class="card"><h1>Hello, CSS!</h1><p class="intro">Small steps build confidence.</p><div class="items"><span>Learn</span><span>Try</span><span>Review</span></div><button type="button">Keep learning</button></article></main>'
css_rows=[
('first','Your first CSS rule','CSS controls presentation. A rule has a selector, which chooses elements, and declarations inside braces. Each declaration pairs a property with a value. HTML supplies the content; CSS changes how it looks.','One rule can style many matching elements consistently.','h1 { color: purple; }',['h1 selects heading elements.','color is the property; purple is its value. The colon joins the pair and the semicolon ends it.','For the task, set the heading color to navy.'],'Make the h1 heading navy.','h1 {\n  color: navy;\n}','Which part chooses the elements?',['Selector','Property value','Semicolon'],0,'The selector appears before the braces and determines which elements the rule matches.','Use color: navy, not color = navy. CSS declarations use colons.','Change the heading to a different named color and compare it.',[('h1','color','rgb(0, 0, 128)','Navy heading')]),
('classes','Style a class of elements','A class attribute marks a reusable group in HTML. A CSS class selector starts with a dot. .intro matches class="intro"; it does not require an element literally named intro.','Classes let you target a design role without styling every paragraph.','.intro { color: teal; }',['Find class="intro" in the supplied HTML.','Use .intro as the selector; the dot belongs in CSS, not in the HTML class value.','Set that paragraph to a font size of 20px.'],'Give .intro a font size of 20px.','.intro {\n  font-size: 20px;\n}','How do you select class="intro"?',['intro','.intro','#intro'],1,'A leading dot identifies a class selector. # selects an id instead.','A missing dot targets an element name, so the rule may match nothing.','Give only this paragraph a different color as well.',[('.intro','font-size','20px','Intro text at 20px')]),
('type','Make text comfortable to read','font-size controls the text size; line-height controls the height of each line box. A unitless line-height is multiplied by the element font size. Generous line spacing can improve readability.','Readable text matters more than decorative effects in a learning interface.','.intro { font-size: 16px; line-height: 1.5; }',['The font size is 16 pixels.','A line-height of 1.5 gives a 24-pixel line box here.','For the task, use 18px and 1.5, which gives 27px.'],'Style .intro with font-size 18px and line-height 1.5.','.intro {\n  font-size: 18px;\n  line-height: 1.5;\n}','What line height results from 18px × 1.5?',['12px','27px','18px'],1,'The unitless multiplier scales with the font size: 18 times 1.5 is 27.','A fixed tiny line-height can cause lines to overlap when text gets larger.','Resize the preview and see how line wrapping differs from line spacing.',[('.intro','font-size','18px','18px paragraph text'),('.intro','line-height','27px','1.5 line spacing')]),
('spacing','Understand the box model','Every element has a content area, padding inside the border, a border, and margin outside it. Padding separates content from the edge; margin separates the element from its neighbors.','Understanding these layers makes spacing predictable.','.card { padding: 12px; margin: 8px; border: 1px solid gray; }',['Start at the text and move outward: content, padding, border, margin.','Padding changes the space inside the card. Margin changes the space outside it.','Use 24px padding and a 2px solid navy border in the task.'],'Give .card 24px padding on all sides and a 2px solid navy border.','.card {\n  padding: 24px;\n  border: 2px solid navy;\n}','Which property creates space inside the border?',['margin','padding','display'],1,'Padding belongs between content and border. Margin is outside the border.','Adding padding can increase the total width under the default content-box model.','Add 16px margin and notice that it moves the entire card.',[('.card','padding-top','24px','Top padding'),('.card','padding-right','24px','Right padding'),('.card','padding-bottom','24px','Bottom padding'),('.card','padding-left','24px','Left padding'),('.card','border-top-width','2px','2px border'),('.card','border-top-style','solid','Solid border'),('.card','border-top-color','rgb(0, 0, 128)','Navy border')]),
('sizing','Keep widths predictable','With box-sizing: border-box, an explicit width includes padding and border. max-width limits growth while width: 100% lets the box fit a narrower parent. These are useful building blocks for responsive layout.','A card should fit a small screen without becoming excessively wide on a large screen.','.card { box-sizing: border-box; width: 100%; max-width: 500px; }',['border-box keeps padding and borders inside the specified width.','width: 100% follows the parent width.','max-width caps growth at 500px.'],'Set .card to border-box sizing, width 100%, and max-width 500px.','.card {\n  box-sizing: border-box;\n  width: 100%;\n  max-width: 500px;\n}','What does border-box include in a declared width?',['Content only','Content, padding and border'],1,'Padding and border are included, so they do not add extra width beyond the declared width.','max-width is a ceiling, not a requirement that the element must always be that wide.','Add padding and shrink the preview to compare how the card fits.',[('.card','box-sizing','border-box','Border-box sizing'),('.card','max-width','500px','Maximum width 500px')]),
('flex','Arrange a row with Flexbox','display: flex makes the direct children of a container flex items. gap adds consistent space between them. justify-content distributes free space along the main axis; align-items aligns on the cross axis.','Flexbox is useful for a toolbar or a row of related controls.','.items { display: flex; gap: 8px; }',['Apply display to the parent .items, not to each span.','Its direct child spans become flex items in a row by default.','For the task, set gap to 12px and justify-content to space-between.'],'Make .items a flex container with a 12px gap and space-between distribution.','.items {\n  display: flex;\n  gap: 12px;\n  justify-content: space-between;\n}','Where does display: flex belong here?',['On the parent .items','Only on the first span'],0,'The parent establishes the flex formatting context for its direct children.','gap is minimum spacing; space-between may add extra free space.','Try flex-direction: column to see how the main axis changes.',[('.items','display','flex','Flex container'),('.items','column-gap','12px','12px gap'),('.items','justify-content','space-between','Distributed items')]),
('grid','Build a small grid','CSS Grid arranges items in rows and columns. grid-template-columns defines the columns; repeat(3, 1fr) makes three equal shares of the available space. gap separates tracks.','Grid helps with two-dimensional layouts such as a collection of learning topics.','.items { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }',['The parent establishes the grid.','Three 1fr tracks share the available space equally after gaps.','Use a 10px gap for the exercise.'],'Make .items a grid with three equal columns and a 10px gap.','.items {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 10px;\n}','What does 1fr represent?',['A share of available space','One pixel','One HTML element'],0,'fr is a flexible fraction of the available space in the grid container.','Grid belongs on the parent. Setting it on each child will not arrange the siblings.','Change to two columns and observe where the third item goes.',[('.items','display','grid','Grid container'),('.items','column-gap','10px','10px gap'),('.items','grid-template-columns','three-equal','Three equal columns')]),
('responsive','Adapt to a narrow screen','A media query applies rules only when its condition matches. A narrow viewport may need stacked items while a wider viewport can show a row. Build a usable default, then enhance it.','Responsive design adapts content to available space rather than assuming every device is a desktop.','.items { display: flex; flex-direction: column; }\n@media (min-width: 600px) {\n  .items { flex-direction: row; }\n}',['The default column layout works on a small viewport.','The media query overrides direction once the viewport is at least 600px wide.','Check both the narrow and wide preview modes; CSS queries use the preview frame width.'],'Stack .items in a flex column below 600px. Use a row at 600px and wider.','.items {\n  display: flex;\n  flex-direction: column;\n}\n@media (min-width: 600px) {\n  .items { flex-direction: row; }\n}','When does min-width: 600px match?',['At 600px and wider','Only below 600px'],0,'min-width includes its boundary and larger viewport widths.','The preview width determines the media query result, not the full app window.','Try a 700px breakpoint and explain the changed transition.',[('.items','display','flex','Narrow flex layout',360),('.items','flex-direction','column','Column at 360px',360),('.items','flex-direction','row','Row at 800px',800)]),
('cascade','Understand which rule wins','The cascade resolves competing declarations. For ordinary author rules in this exercise, a class selector is more specific than an element selector. If specificity is equal, the later rule wins. Inheritance lets some properties pass from parents to children.','When a style seems ignored, inspect which rules actually match instead of adding random overrides.','p { color: red; }\n.intro { color: navy; }',['Both selectors match the intro paragraph.','The class selector is more specific, so its navy declaration wins.','Use a class rule to make the paragraph teal while keeping the general red rule.'],'Keep p { color: red; } and add a more specific .intro rule that makes the paragraph teal.','p { color: red; }\n.intro { color: teal; }','Which selector is more specific here?',['p','.intro'],1,'A class selector is more specific than an element selector in these otherwise comparable rules.','Avoid using !important as your first fix. Understand the competing selectors first.','Add a later .intro color rule and predict which of the two class rules wins.',[('.intro','color','rgb(0, 128, 128)','Teal paragraph')]),
('project','Mini project: a readable learning card','Combine type, spacing, sizing and layout into a card. A coherent design uses a few deliberate choices consistently. This project checks concrete properties; you should also inspect readability and keyboard focus yourself.','A small finished component lets you practise making several rules work together.','.card { padding: 24px; }\n.intro { line-height: 1.5; }',['Keep the card at most 500px wide with border-box sizing and 24px padding.','Use a white background and navy text for a clear starting palette.','Arrange the topic items in a wrapping flex row with a 12px gap. Preserve the native button focus indicator.'],'Style .card with border-box, max-width 500px, padding 24px, white background and navy text. Make .items a wrapping flex row with gap 12px.','.card {\n  box-sizing: border-box;\n  width: 100%;\n  max-width: 500px;\n  padding: 24px;\n  background-color: white;\n  color: navy;\n}\n.items {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n}','Why allow the items to wrap?',['To fit limited horizontal space','To hide all the text'],0,'Wrapping lets items move to a new line when a single row cannot fit.','Do not remove outline without replacing it with a visible focus style. Keyboard users need to see their position.','Add your own border and heading style. Test both widths and navigate to the button with Tab.',[('.card','box-sizing','border-box','Predictable sizing'),('.card','max-width','500px','Width limit'),('.card','padding-top','24px','Card padding'),('.card','background-color','rgb(255, 255, 255)','White background'),('.card','color','rgb(0, 0, 128)','Navy text'),('.items','display','flex','Flex items'),('.items','flex-wrap','wrap','Items can wrap'),('.items','column-gap','12px','12px gap')])]
for row in css_rows:
 slug,title,concept,why,ex,walk,task,sol,q,opts,ans,exp,pit,challenge,checks=row
 rules=[dict(selector=x[0],property=x[1],value=x[2],label=x[3],width=x[4] if len(x)>4 else 800) for x in checks]
 add('css',slug,title,concept,why,ex,walk,task,sol,'',q,opts,ans,exp,pit,challenge,checks=rules,fixture=fixture,terms=[['Selector','Chooses the elements a CSS rule applies to.'],['Declaration','A property and value, such as color: navy.']])
